import re
import sys

assignment = re.compile(
    r"\s*(a|b|TMP)\s*<-\s*"
    r"(?:(\d+)|\(\s*(a|b|TMP)\s*\+\s*(\d+)\s*\)\s*mod\s*100)"
    r"\s*;\s*"
)

values = {}

for line in sys.stdin:
    match = assignment.fullmatch(line)
    if match is None:
        continue

    target, direct, source, increment = match.groups()
    if direct is not None:
        values[target] = int(direct)
    else:
        values[target] = (values[source] + int(increment)) % 100

print(f"a ?= {values['a']}; b ?= {values['b']}; TMP ?= {values['TMP']};")
